/* Real .xlsx workbooks; text cells are never interpreted as formulas. */
window.GrowExcel={
 async buffer(sheets){const wb=new ExcelJS.Workbook();wb.creator='Grow High';wb.created=new Date();for(const {name,headers,rows} of sheets){const ws=wb.addWorksheet(name.slice(0,31));ws.addRow(headers);for(const row of rows)ws.addRow(row.map(v=>v==null?'':typeof v==='number'?v:String(v)));ws.getRow(1).font={bold:true,color:{argb:'FFFFFFFF'}};ws.getRow(1).fill={type:'pattern',pattern:'solid',fgColor:{argb:'FF187EFA'}};ws.views=[{state:'frozen',ySplit:1}];ws.columns.forEach((c,i)=>c.width=Math.min(45,Math.max(16,String(headers[i]||'').length+3)));ws.autoFilter={from:{row:1,column:1},to:{row:Math.max(1,rows.length+1),column:headers.length}};}return wb.xlsx.writeBuffer();},
 async read(file){if(!/\.xlsx$/i.test(file.name))throw Error('Choose an Excel .xlsx workbook. Legacy .xls files are not supported.');if(file.size>2000000)throw Error('Choose a workbook smaller than 2 MB.');const bytes=await file.arrayBuffer(),view=new DataView(bytes);let expanded=0,entries=0;for(let i=0;i+46<view.byteLength;i++){if(view.getUint32(i,true)===0x02014b50){expanded+=view.getUint32(i+24,true);entries++;if(expanded>20000000||entries>250)throw Error('Workbook expands beyond the supported size.');i+=45+view.getUint16(i+28,true)+view.getUint16(i+30,true)+view.getUint16(i+32,true);}}if(!entries)throw Error('This is not a valid Excel workbook.');const wb=new ExcelJS.Workbook();await wb.xlsx.load(bytes);const ws=wb.worksheets[0];if(!ws)throw Error('The workbook has no worksheet.');if(ws.rowCount>501||ws.columnCount>100)throw Error('Use at most 500 data rows and 100 columns.');const value=c=>{const v=c.value;if(v&&typeof v==='object'){if(v instanceof Date)return v.toISOString().slice(0,10);throw Error('Use plain values, not formulas, links or rich-text cells, in the import template.');}return String(v??'').trim();};const headers=[];ws.getRow(1).eachCell({includeEmpty:true},c=>headers.push(value(c)));if(!headers.includes('Name')||!headers.includes('SKU')||headers.some(h=>!h)||new Set(headers).size!==headers.length)throw Error('Use unique headings including Name and SKU. Download the Excel template first.');const rows=[];for(let i=2;i<=ws.rowCount;i++){const values=headers.map((_,j)=>value(ws.getRow(i).getCell(j+1)));if(values.some(Boolean))rows.push(Object.fromEntries(headers.map((h,j)=>[h,values[j]])));}if(!rows.length)throw Error('Add at least one item to the workbook.');return rows;}
};
